macro_rules! inflatePrime {
    () => {
        # [doc = " Inserts bits in the inflate input stream."] # [doc = ""] # [doc = " The intent is that this function is used to start inflating at a bit position in the middle of a byte."] # [doc = " The provided bits will be used before any bytes are used from next_in."] # [doc = " This function should only be used with raw inflate, and should be used before the first [`inflate`] call after [`inflateInit2_`] or [`inflateReset`]."] # [doc = " bits must be less than or equal to 16, and that many of the least significant bits of value will be inserted in the input."] # [doc = ""] # [doc = " If bits is negative, then the input stream bit buffer is emptied. Then [`inflatePrime`] can be called again to put bits in the buffer."] # [doc = " This is used to clear out bits leftover after feeding inflate a block description prior to feeding inflate codes."] # [doc = ""] # [doc = " # Returns"] # [doc = ""] # [doc = " - [`Z_OK`] if success"] # [doc = " - [`Z_STREAM_ERROR`] if the source stream state was inconsistent"] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The caller must guarantee that"] # [doc = ""] # [doc = " * Either"] # [doc = "     - `strm` is `NULL`"] # [doc = "     - `strm` satisfies the requirements of `&mut *strm` and was initialized with [`inflateInit_`] or similar"] # [cfg_attr (feature = "export-symbols" , export_name = prefix ! (inflatePrime))] pub unsafe extern "C-unwind" fn inflatePrime (strm : * mut z_stream , bits : i32 , value : i32) -> i32 { if let Some (stream) = InflateStream :: from_stream_mut (strm) { zlib_rs :: inflate :: prime (stream , bits , value) as _ } else { ReturnCode :: StreamError as _ } }
    };
}

inflatePrime!()